#include <konjugate/sdk/v2/program.hpp>

#include <memory>

namespace k = konjugate::sdk::v2;

namespace {

// PID controller, parallel (independent) form
// Parallel (independent) form:  u = Kp*e + Ki*integral(e) + Kd*de/dt
// where the error is e = setpoint - measurement. The control output is limited to [outputMin, outputMax] when
// outputMax > outputMin, and the integral stops growing while the output is held at a limit it is already pushing
// against (conditional integration), so it does not wind up. The derivative is taken on the error and passed through a
// first-order filter of time constant filterTime (no filtering when that is zero or less). The integral of the error,
// not the integral term itself, is what is remembered, so changing a gain while a run is going does not make the
// output jump.
//
// A digital controller: at every accepted step, advance() reads the measurement, works out the control signal and keeps it, with what
// the controller remembers (the integral of the error, the last error, the filtered derivative), as memory, which the engine saves and
// restores with checkpoints, so forks and resumed runs carry on exactly. evaluate() gives what advance() kept, so the Control output
// and Error states hold their value through the step.
class PidParallel final : public k::Node {
public:
    k::Input     measurement{this, "measurement"};
    k::Parameter setpoint   {this, "setpoint"};
    k::Parameter kp         {this, "kp"};
    k::Parameter ki         {this, "ki"};
    k::Parameter kd         {this, "kd"};
    k::Constant  filterTime {this, "filterTime"};
    k::Constant  outputMin  {this, "outputMin"};
    k::Constant  outputMax  {this, "outputMax"};
    k::Output    control    {this, "control"};   // the Control output state
    k::Output    error      {this, "error"};     // the Error state

    k::Memory<double> integral          {this, "integral", 0.0};
    k::Memory<double> previousError     {this, "previousError", 0.0};
    k::Memory<double> filteredDerivative{this, "filteredDerivative", 0.0};
    k::Memory<bool>   havePrevious      {this, "havePrevious", false};
    k::Memory<double> heldControl       {this, "heldControl", 0.0};
    k::Memory<double> heldError         {this, "heldError", 0.0};

    void evaluate(double, const k::Inputs& x, k::Outputs& y) const override {
        y[control] = x[heldControl];
        y[error] = x[heldError];
    }

    void advance(const k::Step& step, const k::Inputs& x, k::MemoryWriter& m) const override {
        const double stepSize = step.size;
        const double e = x[setpoint] - x[measurement];

        double derivative = 0;
        double filtered = x[filteredDerivative];
        if (x[havePrevious] && stepSize > 0) {
            const double raw = (e - x[previousError]) / stepSize;
            if (x[filterTime] > 0) filtered += stepSize / (x[filterTime] + stepSize) * (raw - filtered);
            else filtered = raw;
            derivative = filtered;
        }

        double sum = x[integral] + (stepSize > 0 ? e * stepSize : 0);
        double u = x[kp] * e + x[ki] * sum + x[kd] * derivative;

        if (x[outputMax] > x[outputMin]) {
            if (u > x[outputMax]) {
                u = x[outputMax];
                if (e > 0) sum = x[integral];
            } else if (u < x[outputMin]) {
                u = x[outputMin];
                if (e < 0) sum = x[integral];
            }
        }

        m[integral] = sum;
        m[previousError] = e;
        m[filteredDerivative] = filtered;
        m[havePrevious] = true;
        m[heldControl] = u;
        m[heldError] = e;
    }
};

}

std::unique_ptr<k::Program> createProgram() { return std::make_unique<PidParallel>(); }
